pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address attacker, bytes memory data) public {
        // Bound amount to something reasonable and ensure attacker is not zero address
        bound(amount, 1, 1000 ether);
        vm.assume(attacker != address(0) && attacker != c.Owner());

        // Deploy a helper that always reverts on call
        Reverter reverter = new Reverter();
        bytes memory reverterData = abi.encodeWithSelector(Reverter.doRevert.selector);

        // Fund the contract with 'amount' Ether via the Owner
        vm.deal(c.Owner(), amount);
        vm.prank(c.Owner());
        (bool contributed,) = address(c).call{value: amount}("");
        require(contributed, "contribution failed");

        uint256 balanceBefore = address(c).balance;

        // Owner calls Command targeting the Reverter with doRevert() data, which reverts.
        // The external call reverts, but Command itself does not revert because adr.call{value: msg.value}(data)
        // returns false and Command ignores it.
        vm.prank(c.Owner());
        c.Command(address(reverter), reverterData);

        // After Command completes, the contract balance should be unchanged.
        assertTrue(address(c).balance == balanceBefore);
    }
}

contract Reverter {
    function doRevert() external pure {
        revert("Reverter: forced revert");
    }
}

